  lms: [{"id":"station","name":"南宁火车站","tx":166,"ty":89,"kind":"station","foot":[5,3],"desc":"1955 年启用的老站，绿皮车年代的南宁门户。站前广场永远有人拖着行李箱，夜里也亮着灯。","tip":"老南宁说的「去南宁」多半指这里，而不是东站。"},{"id":"chaoyang","name":"朝阳广场","tx":172,"ty":100,"kind":"plaza","foot":[1,1],"desc":"老市中心，百货大楼、新华街、满街人潮。逛完一圈手里会多一袋酸嘢和一杯糖水。","tip":"南宁人说「朝阳」不是地名，是「去市区」的意思。"},{"id":"peoples","name":"人民公园","tx":182,"ty":87,"kind":"park","foot":[3,2],"desc":"望仙坡上的老公园，镇宁炮台、白龙潭、九曲桥。早上的老人比树还密，也永远不缺下棋的。","tip":"镇宁炮台是 1917 年留下来的真炮，不是道具。"},{"id":"san","name":"三街两巷","tx":170,"ty":103,"kind":"oldstreet","foot":[5,3],"desc":"兴宁路、民生路、解放路的老骑楼群，青砖黛瓦里藏着糖水铺和旧照相馆。","tip":"「三街」指兴宁路、民生路、解放路，「两巷」是金狮巷和银狮巷。"},{"id":"zhongshan","name":"中山路美食街","tx":173,"ty":107,"kind":"foodstreet","foot":[5,3],"desc":"一条街吃掉半座南宁：老友粉、粉饺、卷筒粉、柠檬鸭、酸嘢，从天黑吃到凌晨。","tip":"老友粉的「老友」是酸笋加豆豉熬出来的味道，不是朋友。"},{"id":"minzu","name":"民族广场","tx":186,"ty":105,"kind":"plaza","foot":[2,1],"desc":"民族大道西端的开阔广场，背后是广西民族艺术宫，节假日的升旗和晚会都在这儿。","tip":"广场地砖缝里种的是三角梅，开花时是紫红色一片。"},{"id":"nanhu","name":"南湖公园","tx":200,"ty":113,"kind":"lake","foot":[0,0],"desc":"城市正中的湖，环湖跑道、荷花池、傍晚的风。南宁人下班后「去南湖跑两圈」是日常。","tip":"南湖其实是邕江故道留下的一段水面，不是人工挖的。"},{"id":"jinhu","name":"金湖广场","tx":222,"ty":104,"kind":"tower","foot":[3,3],"desc":"民歌湖、地王大厦、成片写字楼，南宁的「陆家嘴」。晚上灯光一亮，湖面全是倒影。","tip":"地王大厦顶上能看见整条民族大道，是拍城市照的好位置。"},{"id":"wanxiang","name":"万象城","tx":245,"ty":106,"kind":"mall","foot":[5,4],"desc":"民族大道上的大商场，吃饭、看展、买杯奶茶能泡一整天。周末停车位是硬仗。","tip":"门口那排凤凰木，六月开花时红得像着火。"},{"id":"huizhan","name":"南宁国际会展中心","tx":231,"ty":110,"kind":"conference","foot":[4,4],"desc":"朱槿花造型的大穹顶，中国—东盟博览会的主会场。每年九月全世界来这儿谈生意。","tip":"穹顶是南宁市花朱槿花的形状，白色花瓣一共 12 片。"},{"id":"qingxiu","name":"青秀山","tx":222,"ty":129,"kind":"mountain","foot":[3,2],"desc":"邕江边的城市绿肺，龙象塔、苏铁园、观音禅寺。爬到山顶能把整座南宁收进眼里。","tip":"山里有国内最大的苏铁园，恐龙时代活下来的植物。"},{"id":"dongzhan","name":"南宁东站","tx":266,"ty":73,"kind":"estation","foot":[7,3],"desc":"高铁门户，站房大得能迷路。看到「东站」两个字，不是回家就是出发。","tip":"东站离市区比机场还远一点，但去广州只要三个多小时。"},{"id":"gxu","name":"广西大学","tx":143,"ty":84,"kind":"campus","foot":[4,2],"desc":"西乡塘的老校园，大榕树、旧教学楼、排长队的食堂，还有一届届从这里散场的毕业生。","tip":"西大的榕树年纪比很多学生都大，树荫能罩住一整条路。"},{"id":"bridge","name":"邕江大桥","tx":169,"ty":108,"kind":"bridge","foot":[0,0],"desc":"1964 年通车的邕江第一桥，桥上走一走，江风、货船、黄昏全在。","tip":"它通车那年，南宁人第一次不用坐轮渡过江。"},{"id":"tingzi","name":"江南水街 · 亭子码头","tx":174,"ty":127,"kind":"waterstreet","foot":[4,2],"desc":"江南区的老码头，江风、夜市、排档，老友粉的另一种味道。","tip":"亭子码头以前是水运码头，江边现在还留着旧石阶。"},{"id":"wuxiang","name":"五象湖公园","tx":236,"ty":187,"kind":"lake","foot":[0,0],"desc":"五象新区的新城湖，草坪宽得能放风筝，周围是造型各异的场馆和成片新楼。","tip":"五象新区十年前还是一片丘陵，现在是南宁的天际线。"}],
